const item = $input.first();
const res = item.json || {};
const r = res.result || {};
const expectedFragment = '8330e413-6917-43cd-8171-7ad89dcc5fd3';
const knownGoodUrl = 'https://aborakan.app.n8n.cloud/webhook/8330e413-6917-43cd-8171-7ad89dcc5fd3/webhook';
const currentUrl = r.url || '';
const pendingCount = r.pending_update_count || 0;
const lastErrorDate = r.last_error_date || 0;
const lastErrorMessage = r.last_error_message || '';
const nowSec = Math.floor(Date.now() / 1000);
const errorAgeMin = lastErrorDate ? Math.floor((nowSec - lastErrorDate) / 60) : null;

let healthy = true;
let reason = '';

if (!res.ok) {
  healthy = false;
  reason = 'فشل استدعاء getWebhookInfo نفسه (' + JSON.stringify(res).slice(0, 200) + ')';
} else if (!currentUrl) {
  healthy = false;
  reason = 'لا يوجد ويبهوك مسجل إطلاقًا لدى تيليجرام (url فارغ)';
} else if (currentUrl.indexOf(expectedFragment) === -1) {
  healthy = false;
  reason = 'الويبهوك المسجل لا يطابق بوت العميل المتوقع. المسجل حاليًا: ' + currentUrl;
} else if (errorAgeMin !== null && errorAgeMin < 30 && pendingCount > 0) {
  healthy = false;
  reason = 'تيليجرام يسجل فشل تسليم حديث (منذ ' + errorAgeMin + ' دقيقة) مع ' + pendingCount + ' تحديث متراكم. رسالة الخطأ: ' + lastErrorMessage;
}

const expectedUrl = (currentUrl && currentUrl.indexOf(expectedFragment) !== -1) ? currentUrl : knownGoodUrl;

return { json: {
  healthy,
  reason,
  currentUrl,
  expectedUrl,
  pendingCount,
  lastErrorDate,
  lastErrorMessage,
  checkedAt: new Date().toISOString()
} };

